from rdh import story
READ18 = [story("A Busy Day", "Idiom",
 "Rani: Why are you busy as a bee today, Tom? Tom: I have a test tomorrow. I must hit the books. Rani: Is it hard? Tom: Not really. The last test was a piece of cake. But it is raining cats and dogs, so I cannot go out. Rani: Don't tell Dina about her birthday party. Tom: I will not let the cat out of the bag. Rani: Break a leg tomorrow!",
 "Rani: Mengapa kamu sangat sibuk hari ini, Tom? Tom: Besok aku ada ujian. Aku harus belajar giat. Rani: Apakah sulit? Tom: Tidak juga. Ujian terakhir sangat mudah. Tetapi hujan sangat deras, jadi aku tidak bisa keluar. Rani: Jangan beri tahu Dina tentang pesta ulang tahunnya. Tom: Aku tidak akan membocorkan rahasianya. Rani: Semoga sukses besok!",
 ("Why is Tom busy?", "He has a test tomorrow.", "He has a party tonight.", "He is cooking dinner.", "He is cleaning the house.", "Tom: \"I have a test tomorrow.\""),
 ("It is raining cats and dog.", "I must hit the books.", "I will not let the cat out of the bag.", "Break a leg tomorrow!", "Idiomnya: raining cats and dogs (dogs jamak)."),
 ('Choose the correct word: "The last test was a piece of ___."', "cake", "bread", "rice", "fruit", "A piece of cake = sangat mudah."),
 [("Aku harus belajar giat.", "I must hit the ___.", "books", "Hit the books = belajar giat."),
  ("Hujan sangat deras.", "It is raining ___ and dogs.", "cats", "Raining cats and dogs = hujan deras.")],
 ("Aku tidak akan membocorkan rahasia.", "I will not let the cat out of the bag.", "dog", "Let the cat out of the bag = membocorkan rahasia."))]
